def f(x, y, z, a, b, c):
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Calculate results for Q3 = f(1, 1, 1)
a, b, c = 1, 1, 1
unique_results = set()

for x in range(10):
    for y in range(10):
        for z in range(10):
            result = f(x, y, z, a, b, c)
            unique_results.add(result)

print(f"Cardinality of output set for Q3=(1, 1, 1): {len(unique_results)}")

